42	    author: '作成者', team: '作成チーム', change: '変更内容', program: 'プログラム', tcode: 'T-Code',
43	    menuPath: 'Menu Path', objType: '区分', cbo: 'CBO', standard: '標準', transaction: 'Transaction',
