134	export const SCRIPT = `
135	(function(){
136	  var NS='http://www.w3.org/2000/svg';
137	  function el(name,attrs){var e=document.createElementNS(NS,name);for(var k in attrs)e.setAttribute(k,attrs[k]);return e;}
138	  function find(svg,anchor){
139	    var m=/^([\\s\\S]*?)(?:#([0-9]+))?$/.exec(String(anchor)),key=m[1],nth=parseInt(m[2]||'1',10)||1;
140	    var all=svg.querySelectorAll('[data-anchor]'),hits=[];
141	    for(var i=0;i<all.length;i++)if(all[i].getAttribute('data-anchor')===key)hits.push(all[i]);
142	    return hits[nth-1]||null;
143	  }
144	  function place(fig){
145	    var svg=fig.querySelector('svg'),list;
146	    try{list=JSON.parse(fig.getAttribute('data-callouts')||'[]');}catch(e){return;}
147	    if(!svg||!list.length||!svg.getScreenCTM)return;
148	    var root=svg.getScreenCTM();if(!root)return;
149	    var inv=root.inverse(),layer=el('g',{'class':'callout-layer'}),used={};
150	    list.forEach(function(c){
151	      var target=find(svg,c[1]);if(!target)return;
152	      var b=target.getBBox(),m=target.getScreenCTM();if(!m)return;
153	      m=inv.multiply(m);
154	      var p=svg.createSVGPoint();p.x=b.x;p.y=b.y;var a=p.matrixTransform(m);
155	      p.x=b.x+b.width;p.y=b.y+b.height;var z=p.matrixTransform(m);
156	      var x=Math.min(a.x,z.x)-3,y=Math.min(a.y,z.y)-3,w=Math.abs(z.x-a.x)+6,h=Math.abs(z.y-a.y)+6;
157	      layer.appendChild(el('rect',{x:x,y:y,width:w,height:h,rx:3,fill:'none',stroke:'#D6336C','stroke-width':2}));
158	      var k=Math.round(x)+':'+Math.round(y),shift=(used[k]||0)*20;used[k]=(used[k]||0)+1;
159	      var cx=x+shift,cy=y;
160	      layer.appendChild(el('circle',{cx:cx,cy:cy,r:10,fill:'#D6336C',stroke:'#FFFFFF','stroke-width':1.5}));
161	      var t=el('text',{x:cx,y:cy+4,'text-anchor':'middle','font-size':12,'font-weight':700,fill:'#FFFFFF','font-family':'Arial,sans-serif'});
162	      t.textContent=String(c[0]);layer.appendChild(t);
163	    });
164	    svg.appendChild(layer);
165	  }
166	  function init(){
167	    var figs=document.querySelectorAll('figure[data-callouts]');
168	    for(var i=0;i<figs.length;i++){try{place(figs[i]);}catch(e){}}
169	    var root=document.documentElement;
170	    try{var saved=localStorage.getItem('sc4sap-manual-theme');if(saved)root.setAttribute('data-theme',saved);}catch(e){}
171	    var tb=document.getElementById('theme-btn');
172	    if(tb)tb.addEventListener('click',function(){
173	      var dark=root.getAttribute('data-theme')==='dark'||(!root.getAttribute('data-theme')&&matchMedia('(prefers-color-scheme: dark)').matches);
174	      var next=dark?'light':'dark';root.setAttribute('data-theme',next);
175	      try{localStorage.setItem('sc4sap-manual-theme',next);}catch(e){}
176	    });
177	    // A screen drawn smaller than its natural size opens at full size on click
178	    // (scrolling sideways inside its frame) and closes on a second click.
179	    var shots=document.querySelectorAll('figure.screen');
180	    for(var j=0;j<shots.length;j++)(function(f){
181	      var s=f.querySelector(':scope>svg');if(!s)return;
182	      var natural=parseFloat(s.getAttribute('width'))||0;
183	      if(!natural||s.getBoundingClientRect().width>=natural-1)return;
184	      f.setAttribute('data-zoom','');
185	      f.addEventListener('click',function(){f.classList.toggle('zoomed');});
186	    })(shots[j]);
187	    var pb=document.getElementById('print-btn');
188	    if(pb)pb.addEventListener('click',function(){window.print();});
189	  }
190	  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
191	})();
192	`;
