// Builds t/test.html = the manual + a test script that drives the edit mode and
// prints the saved page's embedded manual.json into <pre id="out">.
const fs = require('fs');
const dir = process.argv[2];
let h = fs.readFileSync(`${dir}/t/ZSDM24710-v1.0-ko.html`, 'utf8');
const test = `<script>
delete window.showSaveFilePicker; window.showSaveFilePicker = undefined;
var captured = null;
URL.createObjectURL = function (b) { captured = b; return 'blob:x'; };
window.confirm = function () { return true; };
setTimeout(function () {
  var log = [];
  try {
    document.getElementById('edit-btn').click();
    log.push('editing=' + document.body.classList.contains('editing'));
    log.push('editable=' + document.querySelectorAll('[contenteditable=true]').length);
    // 1. edit the title of step 1-1
    var t = document.querySelector('#s1-1 [data-k="title"]');
    t.innerHTML = '수정된 <strong>제목</strong>'; t.dispatchEvent(new Event('input', { bubbles: true }));
    // 2. edit intro.purpose
    var p = document.querySelector('[data-p="intro.purpose"]');
    p.textContent = '목적 수정'; p.dispatchEvent(new Event('input', { bubbles: true }));
    // 3. move step 1-2 up
    var a2 = document.getElementById('s1-2'); a2.querySelector('.ed-tools button').click();
    log.push('after move first=' + document.querySelector('section[data-si="0"] article.step').querySelector('[data-k="title"]').textContent);
    // 4. add a callout on the (new) step 1-2 and drag its badge
    var art = document.getElementById('s1-2');
    var btns = art.querySelectorAll('.ed-tools button'); btns[4].click();
    var badges = art.querySelectorAll('.callout-badge');
    log.push('badges=' + badges.length);
    var g = badges[badges.length - 1], r = g.getBoundingClientRect();
    function pe(type, x, y, el) { (el || document).dispatchEvent(new PointerEvent(type, { bubbles: true, clientX: x, clientY: y })); }
    g.dispatchEvent(new PointerEvent('pointerdown', { bubbles: true, clientX: r.x + 5, clientY: r.y + 5 }));
    pe('pointermove', r.x + 45, r.y + 25); pe('pointerup', r.x + 45, r.y + 25);
    // 5. delete step 4 of scenario 4
    var d = document.querySelector('section[data-si="3"] article.step:last-of-type .ed-tools');
    d.querySelectorAll('button')[3].click();
    // 6. save
    document.querySelector('#ed-bar button.primary').click();
  } catch (e) { log.push('ERR ' + e.message + ' ' + e.stack); }
  setTimeout(function () {
    if (!captured) { document.body.insertAdjacentHTML('beforeend', '<pre id="out">' + log.join('\\n') + '\\nNO BLOB</pre>'); return; }
    captured.text().then(function (html) {
      var m = /id="manual-source">([\\s\\S]*?)<\\/script>/.exec(html);
      var j = JSON.parse(m[1]).manual, s1 = j.scenarios[0].steps;
      log.push('saved step1 title=' + s1[0].title + ' | step2 title=' + s1[1].title);
      log.push('purpose=' + j.intro.purpose);
      var cs = s1[1].callouts; log.push('new callout=' + JSON.stringify(cs[cs.length - 1]));
      log.push('s4 steps=' + j.scenarios[3].steps.length + ' edited=' + JSON.stringify(j.edited));
      log.push('saved has contenteditable=' + /contenteditable/.test(html) + ' ed-tools=' + /class="ed-tools"/.test(html) + ' layer=' + /callout-layer/.test(html));
      log.push('saved html length=' + html.length);
      document.body.insertAdjacentHTML('beforeend', '<pre id="out">' + log.join('\\n').replace(/</g, '&lt;') + '</pre>');
    });
  }, 800);
}, 500);
</script></body>`;
h = h.replace(/<\/body>(?![\s\S]*<\/body>)/, test);
fs.writeFileSync(`${dir}/t/test.html`, h);
console.log('ok');

