    g.dispatchEvent(new PointerEvent('pointerdown', { bubbles: true, clientX: r.x + 5, clientY: r.y + 5 }));
    pe('pointermove', r.x + 45, r.y + 25); pe('pointerup', r.x + 45, r.y + 25);
    // 5. delete step 4 of scenario 4
    var d = document.querySelector('section[data-si="3"] article.step:last-of-type .ed-tools');
    d.querySelectorAll('button')[3].click();
    // 6. save
    document.querySelector('#ed-bar button.primary').click();
  } catch (e) { log.push('ERR ' + e.message + ' ' + e.stack); }
