      log.push('saved html length=' + html.length);
      document.body.insertAdjacentHTML('beforeend', '<pre id="out">' + log.join('\\n').replace(/</g, '&lt;') + '</pre>');
    });
  }, 800);
}, 500);
</script></body>`;
