// Pastes a generated 600x300 image onto step 2-1 in edit mode, then saves and
// reports the embedded step.image / callout pos, and restores the drawn screen.
const fs = require('fs');
const dir = process.argv[2];
let h = fs.readFileSync(`${dir}/t/ZSDM24710-v1.0-ko.html`, 'utf8');
const test = `<script>
window.showSaveFilePicker = undefined;
var captured = null; URL.createObjectURL = function (b) { captured = b; return 'blob:x'; };
setTimeout(function () {
  var log = [];
  document.getElementById('edit-btn').click();
  var art = document.getElementById('s2-1');
  art.dispatchEvent(new MouseEvent('mousedown', { bubbles: true }));
  var c = document.createElement('canvas'); c.width = 600; c.height = 300;
  var x = c.getContext('2d'); x.fillStyle = '#3366aa'; x.fillRect(0, 0, 600, 300);
  c.toBlob(function (b) {
    var dt = new DataTransfer(); dt.items.add(new File([b], 'shot.png', { type: 'image/png' }));
    art.dispatchEvent(new ClipboardEvent('paste', { bubbles: true, clipboardData: dt }));
    setTimeout(function () {
      var fig = art.querySelector('figure.screen');
      log.push('figure image=' + fig.hasAttribute('data-image') + ' badges=' + fig.querySelectorAll('.callout-badge').length);
      log.push('restore button=' + !!Array.prototype.find.call(art.querySelectorAll('.ed-tools button'), function (b) { return b.textContent.indexOf('↺') === 0; }));
      document.querySelector('#ed-bar button.primary').click();
      setTimeout(function () {
        captured.text().then(function (html) {
          var j = JSON.parse(/id="manual-source">([\\s\\S]*?)<\\/script>/.exec(html)[1]).manual;
          var st = j.scenarios[1].steps[0];
          log.push('image=' + (st.image && st.image.width + 'x' + st.image.height + ' ' + st.image.src.slice(0, 22)));
          log.push('pos=' + JSON.stringify(st.callouts.map(function (c) { return c.pos; })));
          var restore = Array.prototype.find.call(art.querySelectorAll('.ed-tools button'), function (b) { return b.textContent.indexOf('↺') === 0; });
          restore.click();
          var f2 = art.querySelector('figure.screen');
          log.push('after restore image=' + f2.hasAttribute('data-image') + ' svg anchors=' + f2.querySelectorAll('[data-anchor]').length + ' frames=' + f2.querySelectorAll('.callout-layer rect').length);
          document.body.insertAdjacentHTML('beforeend', '<pre id="out">' + log.join('\\n') + '</pre>');
        });
      }, 500);
    }, 800);
  });
}, 400);
</script></body>`;
h = h.replace(/<\/body>(?![\s\S]*<\/body>)/, test);
fs.writeFileSync(`${dir}/t/test-img.html`, h);
console.log('ok');

