1	// sc4sap:program-to-manual — the page's edit mode ("Edit" button in the top bar).
2	//
3	// Lets a key user change the finished manual like a slide deck, with no tool
4	// installed and nothing loaded from the network:
5	//   · click any text to change it (bold / code / line breaks survive the round trip)
6	//   · move, duplicate, delete steps; add or delete callouts
7	//   · drag a callout badge to a better place (a leader line keeps it tied to its frame)
8	//   · replace a drawn screen with a real screenshot (button, or Ctrl+V on the step)
9	//   · "Save" downloads the page again with the edited manual.json embedded
10	//     (<script id="manual-source">); `build-manual.mjs --import <file>` reads it
11	//     back, so the next version keeps the user's edits.
12	//
13	// The page keeps working without this script — it only adds behaviour.
14	
15	const LABELS = {
16	  ko: {
17	    edit: '편집', done: '편집 종료', save: '저장', up: '위로', down: '아래로', dup: '복제', del: '삭제',
18	    addCallout: '번호 추가', image: '캡처로 교체', restore: '원래 화면', newCallout: '새 설명을 입력하세요.',
19	    confirmDel: '이 스텝을 삭제할까요?', saved: '저장했습니다. 받은 HTML 파일을 공유하세요.', unsaved: '저장하지 않은 변경이 있습니다.',
20	    hint: '글자를 클릭해 고칩니다 · 번호는 드래그해서 옮깁니다 · 스텝을 클릭한 뒤 Ctrl+V로 캡처를 붙여 넣습니다',
21	    delCallout: '이 번호 삭제', addNote: '설명 추가',
22	  },
23	  en: {
24	    edit: 'Edit', done: 'Done', save: 'Save', up: 'Up', down: 'Down', dup: 'Duplicate', del: 'Delete',
25	    addCallout: 'Add callout', image: 'Use screenshot', restore: 'Original screen', newCallout: 'Type the new instruction.',
26	    confirmDel: 'Delete this step?', saved: 'Saved. Share the downloaded HTML file.', unsaved: 'You have unsaved changes.',
27	    hint: 'Click text to change it · drag a number to move it · click a step and press Ctrl+V to paste a screenshot',
28	    delCallout: 'Delete this callout', addNote: 'Add note',
29	  },
30	  ja: {
31	    edit: '編集', done: '編集終了', save: '保存', up: '上へ', down: '下へ', dup: '複製', del: '削除',
32	    addCallout: '番号追加', image: 'キャプチャに置換', restore: '元の画面', newCallout: '新しい説明を入力してください。',
33	    confirmDel: 'このステップを削除しますか？', saved: '保存しました。ダウンロードした HTML を共有してください。', unsaved: '保存していない変更があります。',
34	    hint: '文字をクリックして修正 · 番号はドラッグで移動 · ステップをクリックして Ctrl+V でキャプチャを貼り付け',
35	    delCallout: 'この番号を削除', addNote: '説明を追加',
36	  },
37	};
38	
39	export const editorLabels = (lang) => LABELS[String(lang || '').slice(0, 2).toLowerCase()] || LABELS.en;
40	
41	export const EDITOR_STYLE = `
