  var fallbackBefore=new WeakMap();
  document.addEventListener('focusin',function(ev){
    if(!editing||Q)return;var e=ev.target.closest&&ev.target.closest('[data-p],[data-k]');if(e&&!fallbackBefore.has(e))fallbackBefore.set(e,valueOf(e));
  });
