  function renumber(){
    sections().forEach(function(sec){
      var si=+sec.getAttribute('data-si');
      articles(sec).forEach(function(art,ti){
        art.setAttribute('data-ti',ti);art.id='s'+(si+1)+'-'+(ti+1);
        art.classList.toggle('page-break',ti>0);
