// Drives the Quill edit mode: guide, bold/highlight, bullet list, move+delete then
// Ctrl+Z twice, autosave draft in IndexedDB, save clears the draft.
const fs = require('fs');
const dir = process.argv[2];
let h = fs.readFileSync(`${dir}/q/ZSDM24710-v1.0-ko.html`, 'utf8');
const test = `<script>
window.showSaveFilePicker = undefined;
var captured = null; URL.createObjectURL = function (b) { captured = b; return 'blob:x'; };
window.confirm = function () { return true; };
function md(el) { el.dispatchEvent(new MouseEvent('mousedown', { bubbles: true, cancelable: true })); }
function ctrlZ() { document.body.dispatchEvent(new KeyboardEvent('keydown', { key: 'z', ctrlKey: true, bubbles: true, cancelable: true })); }
function draft(cb) { var r = indexedDB.open('sc4sap-manual', 1); r.onupgradeneeded = function () { r.result.createObjectStore('drafts'); };
  r.onsuccess = function () { var g = r.result.transaction('drafts').objectStore('drafts').get(location.pathname); g.onsuccess = function () { cb(g.result); }; }; }
var log = [];
setTimeout(function () {
  try {
    localStorage.removeItem('sc4sap-manual-guide-seen');
    log.push('quill loaded=' + !!window.Quill);
    document.getElementById('edit-btn').click();
    var g = document.querySelector('.ed-guide'); log.push('guide shown=' + !!g + ' items=' + (g && g.querySelectorAll('li').length));
    g.querySelector('button').click();
    var titles0 = [].map.call(document.querySelectorAll('section[data-si="0"] article.step [data-k="title"]'), function (e) { return e.textContent; });
    // title: bold + highlight
    var t = document.querySelector('#s1-1 [data-k="title"]'); md(t);
    log.push('mounted=' + t.classList.contains('ed-quill') + ' editor=' + !!t.querySelector('.ql-editor') + ' toolbar em=' + !!t.querySelector('.ql-em'));
    var q = Quill.find(t); q.setText('새 제목 입니다\\n'); q.formatText(0, 1, 'bold', true); q.formatText(2, 2, 'em', true);
    // purpose: two bullet lines
    var p = document.querySelector('[data-p="intro.purpose"]'); md(p);
    log.push('title after unmount html=' + t.innerHTML);
    var q2 = Quill.find(p); q2.setText('첫째\\n둘째\\n'); q2.formatLine(0, 5, 'list', 'bullet');
    md(document.querySelector('h2'));
    log.push('purpose html=' + p.innerHTML);
    // move step 1-2 down, delete step 1-3, then undo both
    document.getElementById('s1-2').querySelectorAll('.ed-tools button')[1].click();
    document.getElementById('s1-3').querySelectorAll('.ed-tools button')[3].click();
    log.push('after move+del count=' + document.querySelectorAll('section[data-si="0"] article.step').length);
    ctrlZ(); ctrlZ();
    var titles1 = [].map.call(document.querySelectorAll('section[data-si="0"] article.step [data-k="title"]'), function (e) { return e.textContent; });
    log.push('order restored=' + (JSON.stringify(titles0.slice(1)) === JSON.stringify(titles1.slice(1))) + ' count=' + titles1.length);
  } catch (e) { log.push('ERR ' + e.message + ' ' + e.stack); }
  setTimeout(function () {
    draft(function (d) {
      log.push('draft saved=' + !!(d && d.html && d.html.length > 1000));
      document.querySelector('#ed-bar button.primary').click();
      setTimeout(function () {
        captured.text().then(function (html) {
          var j = JSON.parse(/id="manual-source">([\\s\\S]*?)<\\/script>/.exec(html)[1]).manual;
          log.push('saved title=' + j.scenarios[0].steps[0].title);
          log.push('saved purpose=' + JSON.stringify(j.intro.purpose));
          log.push('saved steps=' + j.scenarios[0].steps.length);
          var dd = new DOMParser().parseFromString(html, 'text/html');
          log.push('saved clean: ql=' + dd.querySelectorAll('.ql-container,.ql-editor').length + ' guide=' + dd.querySelectorAll('.ed-guide').length + ' title html=' + dd.querySelector('#s1-1 [data-k="title"]').innerHTML);
          draft(function (d2) {
            log.push('draft cleared=' + !d2);
            document.body.insertAdjacentHTML('beforeend', '<pre id="out">' + log.join('\\n').replace(/</g, '&lt;') + '</pre>');
          });
        });
      }, 500);
    });
  }, 2500);
}, 500);
</script></body>`;
h = h.replace(/<\/body>(?![\s\S]*<\/body>)/, test);
fs.writeFileSync(`${dir}/q/test.html`, h);
console.log('ok');

